inline const char *taskJsonForRobotCount(int num_robots) {
    switch (num_robots) {
    case 4:
        return kTasks4;
    case 8:
        return kTasks8;
    case 16:
        return kTasks16;
    default:
        throw std::runtime_error(
            "Panda flat built-in tasks support robot counts 4, 8, and 16");
    }
}

